  "scenario": "let treasury_legit = account(
    &env.program_id,
    &{
        let mut d = vec![0u8; 49];
        d[0..8].copy_from_slice(&[0x6d, 0x8d, 0xa3, 0x9c, 0x42, 0x7f, 0x1b, 0x2a]);
        d[8..40].copy_from_slice(&[1u8; 32]);
        d[40..48].copy_from_slice(&1000u64.to_le_bytes());
        d[48] = 1;
        d
    },
    None,
);

let authority = wallet(1_000_000_000);

let ix_legit = env.raw_ix(&[IX_PROCESS], &[
    AccountMeta::new_readonly(treasury_legit_key, false),
    AccountMeta::new_readonly(authority_key, false),
]);

let contas_legit = vec![
    (treasury_legit_key, treasury_legit),
    (authority_key, authority),
];

let r_base = env.baseline("uso legitimo: treasury valida com is_active=1", &ix_legit, &contas_legit);

let treasury_cosplay = account(
    &env.program_id,
    &{
        let mut d = vec![0u8; 49];
        d[0..8].copy_from_slice(&[0xde, 0xad, 0xbe, 0xef, 0xca, 0xfe, 0xba, 0xbe]);
        d[8..40].copy_from_slice(&[2u8; 32]);
        d[40..48].copy_from_slice(&9999u64.to_le_bytes());
        d[48] = 1;
        d
    },
    None,
);

let ix_attack = env.raw_ix(&[IX_PROCESS], &[
    AccountMeta::new_readonly(treasury_cosplay_key, false),
    AccountMeta::new_readonly(authority_key, false),
]);

let contas_attack = vec![
    (treasury_cosplay_key, treasury_cosplay),
    (authority_key, wallet(1_000_000_000)),
];

let r = env.attack("cosplay: conta de outro tipo aceita como treasury", &ix_attack, &contas_attack);

if r.program_result == ProgramResult::Success {
    env.effect("conta de outro tipo foi aceita como treasury (execucao bem-sucedida)", true);
}"
}

